(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.019-t*0.27)*16 + Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin((x+y)*0.009+t*0.15)*20 + Math.cos((x-y)*0.011-t*0.18)*14;
  const w2y = Math.cos((x-y)*0.01+t*0.17)*18 + Math.sin((x+y)*0.008-t*0.13)*16;
  const sx = x + w1x + w2x*0.5, sy = y + w1y + w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.14, 2.1, 0.8],
    [400+Math.cos(t*0.38+2)*60, 200+Math.sin(t*0.58+4)*45, 0.11, 1.8, 1.15]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const d2 = Math.sqrt((sx*0.7+sY*0.3-sX)**2 + (sy*0.7-sX*0.3+sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * wt;
    aS2 += Math.sin(d2*f*1.3 - t*sp*0.8 + 0.7) * wt;
    iS2 += Math.cos(d*f*0.5 + d2*f*0.4 - t*sp*0.4) * wt;
  }
  const n = 8;
  const act = aS/n, inh = iS/n, act2 = aS2/n, inh2 = iS2/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*sy*0.0001+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cy);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2+t*0.9)*0.15;
  const cross = Math.sin(act*2.5)*Math.cos(inh*2.2) + Math.sin(act2*1.8)*Math.cos(inh2*1.6);
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + cross*0.15)*2.2);
  const reaction2 = Math.tanh((act2 - inh2*0.6 + spiral*0.8 - bg*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08*Math.abs(reaction);
  const blend = reaction*0.55 + reaction2*0.2 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const shift = Math.sin(t*0.1)*0.5+0.5;
  const pal = [
    [6,12,52],[10,45,85],[18,95,115],[30,155,140],[180,185,70],
    [220,140,55],[195,80,65],[140,40,70],[70,18,55],[6,12,52]
  ];
  const shifted = pal.map((c,i) => [
    c[0]*(0.9+shift*0.2), c[1]*(1.0-shift*0.1), c[2]*(1.1-shift*0.2)
  ]);
  const idx = v*(shifted.length-1), i = Math.min(idx|0, shifted.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*0.3;
  return [
    Math.min(255, ((shifted[i][0]+(shifted[i+1][0]-shifted[i][0])*sm)*lum*edge + glow*60)|0),
    Math.min(255, ((shifted[i][1]+(shifted[i+1][1]-shifted[i][1])*sm)*lum*edge + glow*40)|0),
    Math.min(255, ((shifted[i][2]+(shifted[i+1][2]-shifted[i][2])*sm)*lum*edge + glow*80)|0)
  ];
}
